pub(super) fn extract_docs<'a>(env: Env<'a>) -> NifResult<Term<'a>> {
    let mut result = Vec::new();
    result.push(map(
        env,
        &[
            ("flag", atom(env, "owner")?),
            ("default_doc", "Do not try to set owner/group.".encode(env)),
        ],
    )?);
    result.push(map(
        env,
        &[
            ("flag", atom(env, "perm")?),
            (
                "default_doc",
                "Do obey umask, do not restore SUID/SGID/SVTX bits.".encode(env),
            ),
        ],
    )?);
    result.push(map(
        env,
        &[
            ("flag", atom(env, "time")?),
            ("default_doc", "Do not restore mtime/atime.".encode(env)),
        ],
    )?);
    result.push(map(
        env,
        &[
            ("flag", atom(env, "no_overwrite")?),
            ("default_doc", "Replace existing files.".encode(env)),
        ],
    )?);
    result.push(map(
        env,
        &[
            ("flag", atom(env, "unlink")?),
            (
                "default_doc",
                "Try create first, unlink only if create fails with EEXIST.".encode(env),
            ),
        ],
    )?);
    result.push(map(
        env,
        &[
            ("flag", atom(env, "acl")?),
            ("default_doc", "Do not restore ACLs.".encode(env)),
        ],
    )?);
    result.push(map(
        env,
        &[
            ("flag", atom(env, "fflags")?),
            ("default_doc", "Do not restore fflags.".encode(env)),
        ],
    )?);
    result.push(map(
        env,
        &[
            ("flag", atom(env, "xattr")?),
            ("default_doc", "Do not restore xattrs.".encode(env)),
        ],
    )?);
    result.push(map(env, &[("flag", atom(env, "secure_symlinks")?), ("default_doc", "Do not try to guard against extracts redirected by symlinks. Note: With ARCHIVE_EXTRACT_UNLINK, will remove any intermediate symlink.".encode(env))])?);
    result.push(map(
        env,
        &[
            ("flag", atom(env, "secure_nodotdot")?),
            (
                "default_doc",
                "Do not reject entries with '..' as path elements.".encode(env),
            ),
        ],
    )?);
    result.push(map(
        env,
        &[
            ("flag", atom(env, "no_autodir")?),
            (
                "default_doc",
                "Create parent directories as needed.".encode(env),
            ),
        ],
    )?);
    result.push(map(
        env,
        &[
            ("flag", atom(env, "no_overwrite_newer")?),
            (
                "default_doc",
                "Overwrite files, even if one on disk is newer.".encode(env),
            ),
        ],
    )?);
    result.push(map(
        env,
        &[
            ("flag", atom(env, "sparse")?),
            (
                "default_doc",
                "Detect blocks of 0 and write holes instead.".encode(env),
            ),
        ],
    )?);
    result.push(map(
        env,
        &[
            ("flag", atom(env, "mac_metadata")?),
            (
                "default_doc",
                "Do not restore Mac extended metadata. This has no effect except on Mac OS."
                    .encode(env),
            ),
        ],
    )?);
    result.push(map(env, &[("flag", atom(env, "no_hfs_compression")?), ("default_doc", "Use HFS+ compression if it was compressed. This has no effect except on Mac OS v10.6 or later.".encode(env))])?);
    result.push(map(env, &[("flag", atom(env, "hfs_compression_forced")?), ("default_doc", "Do not use HFS+ compression if it was not compressed. This has no effect except on Mac OS v10.6 or later.".encode(env))])?);
    result.push(map(
        env,
        &[
            ("flag", atom(env, "secure_noabsolutepaths")?),
            (
                "default_doc",
                "Do not reject entries with absolute paths".encode(env),
            ),
        ],
    )?);
    result.push(map(
        env,
        &[
            ("flag", atom(env, "clear_nochange_fflags")?),
            (
                "default_doc",
                "Do not clear no-change flags when unlinking object".encode(env),
            ),
        ],
    )?);
    result.push(map(
        env,
        &[
            ("flag", atom(env, "safe_writes")?),
            (
                "default_doc",
                "Do not extract atomically (using rename)".encode(env),
            ),
        ],
    )?);
    Ok(result.encode(env))
}
